-- Hasiru Nidhi marketplace: complete database setup (all migrations in order).
-- Generated by `npm run db:bundle` — do not edit by hand.
-- Run once on a NEW Supabase project (SQL Editor > New query > paste > Run).
-- It is not safe to run twice; to change an existing database, run only the newest migration files.

-- ======================================================================
-- 20261017000100_core_schema.sql
-- ======================================================================
-- Hasiru Nidhi marketplace — core schema
-- Apply with: supabase db push   (or paste into the Supabase SQL editor, in order)
--
-- Design rules
--  * Every table has Row Level Security enabled (see 20261017000200_rls.sql).
--  * Privileged state changes (booking confirm, listing approve, role change) happen
--    ONLY through SECURITY DEFINER functions below, never through direct table writes.
--  * "current_user in ('authenticated','anon')" identifies a client request; trusted
--    contexts (the SQL editor, the service role, SECURITY DEFINER bodies) are exempt
--    from the guard triggers.

-- Installed in the "extensions" schema (Supabase's convention) so its operator helper functions are not exposed as API functions.
create schema if not exists extensions;
create extension if not exists btree_gist with schema extensions;

-- ---------------------------------------------------------------- enums
create type public.app_role as enum ('traveller', 'host', 'admin');
create type public.property_status as enum ('draft', 'pending_review', 'approved', 'rejected', 'suspended');
create type public.booking_status as enum (
  'requested', 'confirmed', 'rejected', 'cancelled_by_traveller', 'cancelled_by_host', 'completed'
);
create type public.cancellation_policy as enum ('flexible', 'moderate', 'strict');
create type public.price_unit as enum ('per_night', 'per_person_night', 'per_day_visit');
create type public.enquiry_status as enum ('new', 'in_progress', 'resolved', 'spam');

-- ---------------------------------------------------------------- helpers
create function public.today_ist() returns date
language sql stable as $$ select (now() at time zone 'Asia/Kolkata')::date $$;

create function public.touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- ---------------------------------------------------------------- profiles
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text,
  full_name text not null default '',
  phone text,
  role public.app_role not null default 'traveller',
  is_suspended boolean not null default false,
  host_verified boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint profiles_phone_len check (phone is null or char_length(phone) <= 20),
  constraint profiles_name_len check (char_length(full_name) <= 120)
);
create trigger profiles_touch before update on public.profiles
  for each row execute function public.touch_updated_at();

-- Role helpers. SECURITY DEFINER so they can be used inside RLS policies on any table.
create function public.is_admin() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.role = 'admin' and not p.is_suspended
  )
$$;

create function public.is_host() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.role = 'host' and not p.is_suspended
  )
$$;

-- New auth users always become travellers, or hosts if they asked for a host account.
-- 'admin' can NEVER be requested through signup metadata.
create function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_role public.app_role := 'traveller';
begin
  if coalesce(new.raw_user_meta_data ->> 'account_type', '') = 'host' then
    v_role := 'host';
  end if;
  insert into public.profiles (id, email, full_name, phone, role)
  values (
    new.id,
    new.email,
    left(coalesce(new.raw_user_meta_data ->> 'full_name', ''), 120),
    left(nullif(new.raw_user_meta_data ->> 'phone', ''), 20),
    v_role
  )
  on conflict (id) do nothing;
  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- Clients may edit their own name/phone only. role / suspension / verification are locked.
create function public.profiles_guard() returns trigger
language plpgsql as $$
begin
  if current_user in ('authenticated', 'anon') then
    if new.id is distinct from old.id
       or new.role is distinct from old.role
       or new.is_suspended is distinct from old.is_suspended
       or new.host_verified is distinct from old.host_verified
       or new.email is distinct from old.email then
      raise exception 'forbidden_profile_change' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;
create trigger profiles_guard before update on public.profiles
  for each row execute function public.profiles_guard();

-- ---------------------------------------------------------------- catalogue (admin managed)
create table public.property_categories (
  id bigint generated always as identity primary key,
  slug text not null unique,
  name text not null,
  description text,
  sort_order int not null default 0,
  is_active boolean not null default true
);
create table public.amenities (
  id bigint generated always as identity primary key,
  slug text not null unique,
  name text not null,
  group_name text not null default 'general',
  sort_order int not null default 0,
  is_active boolean not null default true
);
create table public.experiences (
  id bigint generated always as identity primary key,
  slug text not null unique,
  name text not null,
  description text,
  sort_order int not null default 0,
  is_active boolean not null default true
);

-- ---------------------------------------------------------------- properties
create table public.properties (
  id uuid primary key default gen_random_uuid(),
  host_id uuid references public.profiles (id) on delete set null, -- NULL = platform managed / sample
  slug text not null unique,
  name text not null,
  category_id bigint references public.property_categories (id),
  summary text,
  description text not null default '',
  city text,
  state text,
  region text,
  postal_code text,
  latitude numeric(9, 6),   -- approximate public location only
  longitude numeric(9, 6),
  rooms_count int not null default 1,
  max_guests int not null default 2,
  price_inr numeric(10, 2),
  price_unit public.price_unit not null default 'per_night',
  check_in_time time not null default '14:00',
  check_out_time time not null default '11:00',
  house_rules text,
  cancellation_policy public.cancellation_policy not null default 'moderate',
  status public.property_status not null default 'draft',
  rejection_reason text,
  reviewed_by uuid references public.profiles (id) on delete set null,
  reviewed_at timestamptz,
  is_featured boolean not null default false,
  is_sample boolean not null default false,
  terms_accepted_at timestamptz,
  submitted_at timestamptz,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint properties_name_len check (char_length(name) between 3 and 120),
  constraint properties_summary_len check (summary is null or char_length(summary) <= 240),
  constraint properties_description_len check (char_length(description) <= 8000),
  constraint properties_rooms check (rooms_count between 1 and 200),
  constraint properties_guests check (max_guests between 1 and 500),
  constraint properties_price check (price_inr is null or (price_inr >= 0 and price_inr <= 10000000))
);
create index properties_status_idx on public.properties (status);
create index properties_host_idx on public.properties (host_id);
create index properties_city_idx on public.properties (lower(city));
create index properties_category_idx on public.properties (category_id);
create trigger properties_touch before update on public.properties
  for each row execute function public.touch_updated_at();

-- Owner-only details that must never be public (address, contact, current platforms).
create table public.property_private (
  property_id uuid primary key references public.properties (id) on delete cascade,
  address_line text,
  contact_name text,
  contact_email text,
  contact_phone text,
  current_platforms text,
  partnership_model text,
  constraint property_private_lens check (
    coalesce(char_length(address_line), 0) <= 300
    and coalesce(char_length(current_platforms), 0) <= 300
    and coalesce(char_length(partnership_model), 0) <= 300
  )
);

create table public.property_amenities (
  property_id uuid not null references public.properties (id) on delete cascade,
  amenity_id bigint not null references public.amenities (id) on delete cascade,
  primary key (property_id, amenity_id)
);
create table public.property_experiences (
  property_id uuid not null references public.properties (id) on delete cascade,
  experience_id bigint not null references public.experiences (id) on delete cascade,
  primary key (property_id, experience_id)
);
create table public.property_images (
  id uuid primary key default gen_random_uuid(),
  property_id uuid not null references public.properties (id) on delete cascade,
  path text not null,                                  -- storage object path, or /images/... for bundled static files
  source text not null default 'storage' check (source in ('storage', 'static')),
  alt text,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);
create index property_images_property_idx on public.property_images (property_id, sort_order);
create table public.room_types (
  id uuid primary key default gen_random_uuid(),
  property_id uuid not null references public.properties (id) on delete cascade,
  name text not null,
  capacity int not null default 2 check (capacity between 1 and 50),
  quantity int not null default 1 check (quantity between 1 and 200),
  price_inr numeric(10, 2) check (price_inr is null or price_inr >= 0),
  description text
);
create index room_types_property_idx on public.room_types (property_id);

-- Dates a host has blocked (maintenance, own use, other platform). end_date is exclusive.
create table public.availability_blocks (
  id uuid primary key default gen_random_uuid(),
  property_id uuid not null references public.properties (id) on delete cascade,
  start_date date not null,
  end_date date not null,
  reason text,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  constraint availability_blocks_range check (end_date > start_date and end_date - start_date <= 366)
);
create index availability_blocks_property_idx on public.availability_blocks (property_id, start_date);

-- ---------------------------------------------------------------- bookings
create table public.bookings (
  id uuid primary key default gen_random_uuid(),
  property_id uuid not null references public.properties (id) on delete restrict,
  traveller_id uuid references public.profiles (id) on delete set null,
  check_in date not null,
  check_out date not null,
  adults int not null,
  children int not null default 0,
  status public.booking_status not null default 'requested',
  message text,
  host_response text,
  -- snapshots so each party keeps a readable record even if the other side edits/deletes data
  property_name text not null,
  cancellation_policy public.cancellation_policy not null,
  guest_name text not null default '',
  guest_email text,
  guest_phone text,
  indicative_total_inr numeric(12, 2),
  responded_at timestamptz,
  cancelled_at timestamptz,
  cancellation_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint bookings_dates check (check_out > check_in and check_out - check_in <= 60),
  constraint bookings_guests check (adults between 1 and 200 and children between 0 and 200),
  constraint bookings_message_len check (coalesce(char_length(message), 0) <= 2000),
  -- THE double-booking guard: two confirmed stays for one property can never overlap.
  constraint bookings_no_confirmed_overlap exclude using gist (
    property_id with =,
    daterange(check_in, check_out, '[)') with &&
  ) where (status = 'confirmed')
);
create index bookings_property_idx on public.bookings (property_id, status);
create index bookings_traveller_idx on public.bookings (traveller_id, created_at desc);
create trigger bookings_touch before update on public.bookings
  for each row execute function public.touch_updated_at();

create table public.saved_properties (
  user_id uuid not null references public.profiles (id) on delete cascade,
  property_id uuid not null references public.properties (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, property_id)
);

-- Reviews exist only for completed, real stays (enforced by RLS in the next migration).
create table public.reviews (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null unique references public.bookings (id) on delete cascade,
  property_id uuid not null references public.properties (id) on delete cascade,
  traveller_id uuid not null references public.profiles (id) on delete cascade,
  rating int not null check (rating between 1 and 5),
  comment text check (comment is null or char_length(comment) <= 2000),
  is_hidden boolean not null default false,
  created_at timestamptz not null default now()
);
create index reviews_property_idx on public.reviews (property_id) where not is_hidden;

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null,
  title text not null,
  body text,
  link text,
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);
create index notifications_user_idx on public.notifications (user_id, is_read, created_at desc);

-- ---------------------------------------------------------------- enquiries & applications
create table public.contact_enquiries (
  id uuid primary key default gen_random_uuid(),
  kind text not null default 'general'
    check (kind in ('general', 'property', 'group', 'experience_request', 'host_partnership', 'support')),
  name text not null,
  email text,
  phone text,
  subject text,
  message text not null,
  property_id uuid references public.properties (id) on delete set null,
  payload jsonb not null default '{}'::jsonb,
  user_id uuid references public.profiles (id) on delete set null,
  status public.enquiry_status not null default 'new',
  admin_notes text,
  created_at timestamptz not null default now(),
  constraint contact_enquiries_lens check (
    char_length(name) between 1 and 120
    and char_length(message) between 3 and 5000
    and coalesce(char_length(email), 0) <= 254
    and coalesce(char_length(phone), 0) <= 20
    and coalesce(char_length(subject), 0) <= 200
    and pg_column_size(payload) <= 8192
  ),
  constraint contact_enquiries_reachable check (email is not null or phone is not null)
);
create index contact_enquiries_status_idx on public.contact_enquiries (status, created_at desc);

create table public.partner_applications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references public.profiles (id) on delete set null,
  owner_name text not null,
  email text not null,
  phone text not null,
  property_name text not null,
  city text not null,
  state text not null default 'Karnataka',
  category text,
  rooms_count int check (rooms_count is null or rooms_count between 1 and 200),
  max_guests int check (max_guests is null or max_guests between 1 and 500),
  description text,
  current_platforms text,
  partnership_model text,
  consent_at timestamptz not null,
  status text not null default 'new' check (status in ('new', 'contacted', 'invited', 'closed')),
  admin_notes text,
  created_at timestamptz not null default now(),
  constraint partner_applications_lens check (
    char_length(owner_name) <= 120 and char_length(email) <= 254 and char_length(phone) <= 20
    and char_length(property_name) <= 120 and char_length(city) <= 120
    and coalesce(char_length(description), 0) <= 3000
    and coalesce(char_length(current_platforms), 0) <= 300
    and coalesce(char_length(partnership_model), 0) <= 300
  )
);

create table public.gardening_enquiries (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references public.profiles (id) on delete set null,
  name text not null,
  phone text,
  email text,
  location text not null,
  property_type text not null,
  garden_size text,
  services text[] not null default '{}',
  requirements text,
  budget_range text,
  photo_paths text[] not null default '{}',   -- private bucket 'enquiry-photos', admin views via signed URLs
  status public.enquiry_status not null default 'new',
  admin_notes text,
  created_at timestamptz not null default now(),
  constraint gardening_enquiries_lens check (
    char_length(name) <= 120 and char_length(location) <= 200 and char_length(property_type) <= 80
    and coalesce(char_length(garden_size), 0) <= 80
    and coalesce(char_length(requirements), 0) <= 4000
    and coalesce(char_length(budget_range), 0) <= 80
    and coalesce(cardinality(services), 0) <= 20
    and coalesce(cardinality(photo_paths), 0) <= 5
  ),
  constraint gardening_enquiries_reachable check (email is not null or phone is not null)
);

create table public.reports (
  id uuid primary key default gen_random_uuid(),
  property_id uuid not null references public.properties (id) on delete cascade,
  reporter_id uuid references public.profiles (id) on delete set null,
  reason text not null,
  details text,
  status text not null default 'open' check (status in ('open', 'reviewing', 'closed')),
  created_at timestamptz not null default now(),
  constraint reports_lens check (char_length(reason) <= 120 and coalesce(char_length(details), 0) <= 3000)
);

-- ---------------------------------------------------------------- settings & audit
create table public.platform_settings (
  key text primary key,
  value jsonb not null default 'null'::jsonb,
  is_public boolean not null default false,
  description text,
  updated_by uuid references public.profiles (id) on delete set null,
  updated_at timestamptz not null default now()
);
create table public.audit_logs (
  id bigint generated always as identity primary key,
  actor_id uuid,
  action text not null,
  entity_type text not null,
  entity_id text,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index audit_logs_created_idx on public.audit_logs (created_at desc);

-- ---------------------------------------------------------------- guard triggers
-- Owners can edit their listing but cannot approve it, feature it, or reassign it.
create function public.properties_guard() returns trigger
language plpgsql as $$
begin
  if current_user in ('authenticated', 'anon') and not public.is_admin() then
    if tg_op = 'INSERT' then
      if new.status <> 'draft' or new.is_featured or new.is_sample
         or new.reviewed_by is not null or new.published_at is not null
         or new.host_id is distinct from auth.uid() then
        raise exception 'forbidden_property_change' using errcode = '42501';
      end if;
    else
      if new.host_id is distinct from old.host_id
         or new.is_featured is distinct from old.is_featured
         or new.is_sample is distinct from old.is_sample
         or new.reviewed_by is distinct from old.reviewed_by
         or new.reviewed_at is distinct from old.reviewed_at
         or new.published_at is distinct from old.published_at
         or new.submitted_at is distinct from old.submitted_at
         or new.rejection_reason is distinct from old.rejection_reason
         or new.slug is distinct from old.slug then
        raise exception 'forbidden_property_change' using errcode = '42501';
      end if;
      -- Status cannot be changed directly; submit_property()/review_property() do that.
      if new.status is distinct from old.status then
        raise exception 'forbidden_status_change' using errcode = '42501';
      end if;
      -- Material edits to a live listing send it back for re-review.
      if old.status = 'approved' and (
           new.name is distinct from old.name
        or new.description is distinct from old.description
        or new.category_id is distinct from old.category_id
        or new.city is distinct from old.city
        or new.state is distinct from old.state) then
        new.status := 'pending_review';
      end if;
    end if;
  end if;
  return new;
end $$;
create trigger properties_guard before insert or update on public.properties
  for each row execute function public.properties_guard();

-- A host may not block nights that already have a confirmed booking.
create function public.availability_blocks_guard() returns trigger
language plpgsql as $$
begin
  if exists (
    select 1 from public.bookings b
    where b.property_id = new.property_id and b.status = 'confirmed'
      and daterange(b.check_in, b.check_out, '[)') && daterange(new.start_date, new.end_date, '[)')
  ) then
    raise exception 'blocks_confirmed_booking' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger availability_blocks_guard before insert or update on public.availability_blocks
  for each row execute function public.availability_blocks_guard();

-- ---------------------------------------------------------------- internal helpers (not callable by clients)
create function public.notify(p_user uuid, p_kind text, p_title text, p_body text, p_link text)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if p_user is not null then
    insert into public.notifications (user_id, kind, title, body, link)
    values (p_user, p_kind, p_title, p_body, p_link);
  end if;
end $$;

create function public.notify_admins(p_kind text, p_title text, p_body text, p_link text)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
begin
  insert into public.notifications (user_id, kind, title, body, link)
  select id, p_kind, p_title, p_body, p_link from public.profiles
  where role = 'admin' and not is_suspended;
end $$;

create function public.write_audit(p_action text, p_type text, p_id text, p_details jsonb)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
begin
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, details)
  values (auth.uid(), p_action, p_type, p_id, coalesce(p_details, '{}'::jsonb));
end $$;

revoke all on function public.notify(uuid, text, text, text, text) from public, anon, authenticated;
revoke all on function public.notify_admins(text, text, text, text) from public, anon, authenticated;
revoke all on function public.write_audit(text, text, text, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------- RPC: bookings
create function public.request_booking(
  p_property uuid,
  p_check_in date,
  p_check_out date,
  p_adults int,
  p_children int default 0,
  p_message text default null
) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_prof public.profiles%rowtype;
  v_prop public.properties%rowtype;
  v_guests int;
  v_nights int;
  v_total numeric(12, 2);
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  select * into v_prof from public.profiles where id = v_uid;
  if not found or v_prof.is_suspended then
    raise exception 'account_suspended' using errcode = '42501';
  end if;

  select * into v_prop from public.properties where id = p_property and status = 'approved';
  if not found then
    raise exception 'property_unavailable' using errcode = 'P0001';
  end if;
  if v_prop.host_id = v_uid then
    raise exception 'own_property' using errcode = 'P0001';
  end if;

  if p_check_in is null or p_check_out is null or p_check_in < public.today_ist() then
    raise exception 'invalid_dates' using errcode = 'P0001';
  end if;
  if p_check_out <= p_check_in or p_check_out - p_check_in > 30 then
    raise exception 'invalid_dates' using errcode = 'P0001';
  end if;
  v_nights := p_check_out - p_check_in;

  v_guests := coalesce(p_adults, 0) + coalesce(p_children, 0);
  if coalesce(p_adults, 0) < 1 or coalesce(p_children, 0) < 0 or v_guests > v_prop.max_guests then
    raise exception 'invalid_guests' using errcode = 'P0001';
  end if;

  if exists (
    select 1 from public.bookings b
    where b.property_id = p_property and b.status = 'confirmed'
      and daterange(b.check_in, b.check_out, '[)') && daterange(p_check_in, p_check_out, '[)')
  ) or exists (
    select 1 from public.availability_blocks ab
    where ab.property_id = p_property
      and daterange(ab.start_date, ab.end_date, '[)') && daterange(p_check_in, p_check_out, '[)')
  ) then
    raise exception 'dates_unavailable' using errcode = 'P0001';
  end if;

  if exists (
    select 1 from public.bookings b
    where b.property_id = p_property and b.traveller_id = v_uid and b.status = 'requested'
      and daterange(b.check_in, b.check_out, '[)') && daterange(p_check_in, p_check_out, '[)')
  ) then
    raise exception 'duplicate_request' using errcode = 'P0001';
  end if;

  v_total := case
    when v_prop.price_inr is null then null
    when v_prop.price_unit = 'per_night' then v_prop.price_inr * v_nights
    when v_prop.price_unit = 'per_person_night' then v_prop.price_inr * v_nights * v_guests
    else v_prop.price_inr * v_guests
  end;

  insert into public.bookings (
    property_id, traveller_id, check_in, check_out, adults, children, message,
    property_name, cancellation_policy, guest_name, guest_email, guest_phone, indicative_total_inr
  ) values (
    p_property, v_uid, p_check_in, p_check_out, p_adults, coalesce(p_children, 0), nullif(trim(p_message), ''),
    v_prop.name, v_prop.cancellation_policy, v_prof.full_name, v_prof.email, v_prof.phone, v_total
  ) returning id into v_id;

  if v_prop.host_id is not null then
    perform public.notify(v_prop.host_id, 'booking_requested', 'New booking request',
      v_prof.full_name || ' requested ' || v_prop.name || ' for ' || p_check_in || ' to ' || p_check_out || '.',
      '/host/bookings');
  else
    perform public.notify_admins('booking_requested', 'Booking request on a platform-managed listing',
      v_prop.name || ' · ' || p_check_in || ' to ' || p_check_out, '/admin/bookings');
  end if;
  perform public.notify(v_uid, 'booking_requested', 'Request sent',
    'Your request for ' || v_prop.name || ' is with the host. It is not a confirmed reservation yet.',
    '/dashboard/bookings');

  return v_id;
end $$;

create function public.respond_to_booking(p_booking uuid, p_accept boolean, p_note text default null)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  b public.bookings%rowtype;
  v_host uuid;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  select * into b from public.bookings where id = p_booking for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  select host_id into v_host from public.properties where id = b.property_id;
  if not (v_uid = v_host or public.is_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if b.status <> 'requested' then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;

  if p_accept then
    if exists (
      select 1 from public.availability_blocks ab
      where ab.property_id = b.property_id
        and daterange(ab.start_date, ab.end_date, '[)') && daterange(b.check_in, b.check_out, '[)')
    ) then
      raise exception 'dates_unavailable' using errcode = 'P0001';
    end if;
    begin
      update public.bookings
         set status = 'confirmed', host_response = nullif(trim(p_note), ''), responded_at = now()
       where id = b.id;
    exception when exclusion_violation then
      raise exception 'dates_unavailable' using errcode = 'P0001';
    end;
    perform public.notify(b.traveller_id, 'booking_confirmed', 'Booking confirmed',
      b.property_name || ' is confirmed for ' || b.check_in || ' to ' || b.check_out || '.', '/dashboard/bookings');
  else
    update public.bookings
       set status = 'rejected', host_response = nullif(trim(p_note), ''), responded_at = now()
     where id = b.id;
    perform public.notify(b.traveller_id, 'booking_rejected', 'Booking request declined',
      'The host could not accept your request for ' || b.property_name || '.', '/dashboard/bookings');
  end if;
end $$;

create function public.cancel_booking(p_booking uuid, p_note text default null)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  b public.bookings%rowtype;
  v_host uuid;
  v_new public.booking_status;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  select * into b from public.bookings where id = p_booking for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  select host_id into v_host from public.properties where id = b.property_id;

  if v_uid = b.traveller_id then
    v_new := 'cancelled_by_traveller';
  elsif v_uid = v_host or public.is_admin() then
    v_new := 'cancelled_by_host';
  else
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if b.status not in ('requested', 'confirmed') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if b.check_in < public.today_ist() and b.status = 'confirmed' then
    raise exception 'stay_already_started' using errcode = 'P0001';
  end if;

  update public.bookings
     set status = v_new, cancelled_at = now(), cancellation_note = nullif(trim(p_note), '')
   where id = b.id;

  -- The cancellation policy governs any refund; no payment is held by the platform yet,
  -- so refunds are settled directly between traveller and host according to this policy.
  if v_new = 'cancelled_by_traveller' then
    perform public.notify(v_host, 'booking_cancelled', 'Booking cancelled by guest',
      b.guest_name || ' cancelled ' || b.property_name || ' (' || b.check_in || ' to ' || b.check_out || ').', '/host/bookings');
  else
    perform public.notify(b.traveller_id, 'booking_cancelled', 'Booking cancelled by host',
      b.property_name || ' (' || b.check_in || ' to ' || b.check_out || ') was cancelled by the host.', '/dashboard/bookings');
  end if;
end $$;

-- ---------------------------------------------------------------- RPC: listings
create function public.submit_property(p_property uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  p public.properties%rowtype;
  v_missing text[] := '{}';
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  select * into p from public.properties where id = p_property for update;
  if not found or p.host_id is distinct from v_uid then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = v_uid and role = 'host' and not is_suspended) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p.status not in ('draft', 'rejected') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;

  if char_length(trim(p.name)) < 3 then v_missing := array_append(v_missing, 'name'); end if;
  if p.category_id is null then v_missing := array_append(v_missing, 'category'); end if;
  if coalesce(trim(p.city), '') = '' then v_missing := array_append(v_missing, 'city'); end if;
  if coalesce(trim(p.state), '') = '' then v_missing := array_append(v_missing, 'state'); end if;
  if char_length(trim(p.description)) < 50 then v_missing := array_append(v_missing, 'description'); end if;
  if p.terms_accepted_at is null then v_missing := array_append(v_missing, 'terms'); end if;
  if not exists (select 1 from public.property_images i where i.property_id = p.id) then
    v_missing := array_append(v_missing, 'photos');
  end if;
  if not exists (
    select 1 from public.property_private pp
    where pp.property_id = p.id and coalesce(trim(pp.contact_phone), '') <> '' and coalesce(trim(pp.address_line), '') <> ''
  ) then
    v_missing := array_append(v_missing, 'contact_and_address');
  end if;
  if cardinality(v_missing) > 0 then
    raise exception 'incomplete_listing: %', array_to_string(v_missing, ',') using errcode = 'P0001';
  end if;

  update public.properties
     set status = 'pending_review', submitted_at = now(), rejection_reason = null
   where id = p.id;
  perform public.notify_admins('property_submitted', 'Listing awaiting review', p.name, '/admin/properties');
  perform public.notify(v_uid, 'property_submitted', 'Listing submitted',
    p.name || ' is pending review. It will not be public until an administrator approves it.', '/host/properties');
end $$;

create function public.review_property(p_property uuid, p_decision text, p_reason text default null)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  p public.properties%rowtype;
  v_status public.property_status;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select * into p from public.properties where id = p_property for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;

  if p_decision = 'approve' then
    if p.status not in ('pending_review', 'rejected') then
      raise exception 'invalid_status' using errcode = 'P0001';
    end if;
    v_status := 'approved';
  elsif p_decision = 'reject' then
    if p.status <> 'pending_review' then
      raise exception 'invalid_status' using errcode = 'P0001';
    end if;
    if coalesce(trim(p_reason), '') = '' then
      raise exception 'reason_required' using errcode = 'P0001';
    end if;
    v_status := 'rejected';
  elsif p_decision = 'suspend' then
    if p.status <> 'approved' then
      raise exception 'invalid_status' using errcode = 'P0001';
    end if;
    if coalesce(trim(p_reason), '') = '' then
      raise exception 'reason_required' using errcode = 'P0001';
    end if;
    v_status := 'suspended';
  elsif p_decision = 'reinstate' then
    if p.status <> 'suspended' then
      raise exception 'invalid_status' using errcode = 'P0001';
    end if;
    v_status := 'approved';
  else
    raise exception 'invalid_decision' using errcode = 'P0001';
  end if;

  update public.properties
     set status = v_status,
         rejection_reason = case when v_status in ('rejected', 'suspended') then trim(p_reason) else null end,
         reviewed_by = v_uid,
         reviewed_at = now(),
         published_at = case when v_status = 'approved' then coalesce(published_at, now()) else published_at end
   where id = p.id;

  perform public.notify(p.host_id, 'property_' || v_status::text,
    'Listing ' || replace(v_status::text, '_', ' '),
    p.name || case when v_status in ('rejected', 'suspended') then ': ' || trim(p_reason) else '' end,
    '/host/properties');
  perform public.write_audit('property_' || p_decision, 'property', p.id::text,
    jsonb_build_object('reason', p_reason, 'from', p.status, 'to', v_status));
end $$;

create function public.admin_update_user(
  p_user uuid,
  p_role public.app_role default null,
  p_suspended boolean default null,
  p_verified boolean default null
) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  t public.profiles%rowtype;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select * into t from public.profiles where id = p_user for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if t.role = 'admin' or p_role = 'admin' then
    -- Admins are created and removed only through the documented SQL procedure.
    raise exception 'admin_changes_not_allowed' using errcode = '42501';
  end if;
  update public.profiles
     set role = coalesce(p_role, role),
         is_suspended = coalesce(p_suspended, is_suspended),
         host_verified = coalesce(p_verified, host_verified)
   where id = p_user;
  perform public.write_audit('user_update', 'profile', p_user::text,
    jsonb_build_object('role', p_role, 'suspended', p_suspended, 'verified', p_verified));
end $$;

-- ---------------------------------------------------------------- RPC: public read helpers
create function public.property_unavailable_ranges(p_property uuid)
returns table (start_date date, end_date date)
language sql stable security definer set search_path = public, pg_temp as $$
  select b.check_in, b.check_out from public.bookings b
   where b.property_id = p_property and b.status = 'confirmed' and b.check_out > public.today_ist()
     and exists (select 1 from public.properties p where p.id = p_property and p.status = 'approved')
  union all
  select ab.start_date, ab.end_date from public.availability_blocks ab
   where ab.property_id = p_property and ab.end_date > public.today_ist()
     and exists (select 1 from public.properties p where p.id = p_property and p.status = 'approved')
$$;

create function public.is_property_available(p_property uuid, p_from date, p_to date)
returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  -- Runs with owner rights on purpose: availability must reflect ALL confirmed bookings and
  -- host blocks, not only the rows the caller is allowed to read.
  select not exists (
           select 1 from public.bookings b
            where b.property_id = p_property and b.status = 'confirmed'
              and daterange(b.check_in, b.check_out, '[)') && daterange(p_from, p_to, '[)'))
     and not exists (
           select 1 from public.availability_blocks ab
            where ab.property_id = p_property
              and daterange(ab.start_date, ab.end_date, '[)') && daterange(p_from, p_to, '[)'))
$$;

create function public.search_properties(
  p_query text default null,
  p_category text default null,
  p_min_price numeric default null,
  p_max_price numeric default null,
  p_guests int default null,
  p_amenities text[] default null,
  p_experiences text[] default null,
  p_check_in date default null,
  p_check_out date default null,
  p_sort text default 'featured',
  p_limit int default 12,
  p_offset int default 0
) returns table (
  id uuid, slug text, name text, summary text, city text, state text, region text,
  category_slug text, category_name text, price_inr numeric, price_unit public.price_unit,
  max_guests int, rooms_count int, is_featured boolean, is_sample boolean,
  cover_path text, cover_source text, cover_alt text, total_count bigint
)
language sql stable security invoker set search_path = public, pg_temp as $$
  select p.id, p.slug, p.name, p.summary, p.city, p.state, p.region,
         c.slug, c.name, p.price_inr, p.price_unit, p.max_guests, p.rooms_count,
         p.is_featured, p.is_sample,
         img.path, img.source, img.alt,
         count(*) over () as total_count
    from public.properties p
    left join public.property_categories c on c.id = p.category_id
    left join lateral (
      select i.path, i.source, i.alt from public.property_images i
       where i.property_id = p.id order by i.sort_order, i.created_at limit 1
    ) img on true
   where p.status = 'approved'
     and (coalesce(p_query, '') = '' or p.name ilike '%' || p_query || '%'
          or coalesce(p.city, '') ilike '%' || p_query || '%'
          or coalesce(p.region, '') ilike '%' || p_query || '%'
          or coalesce(p.state, '') ilike '%' || p_query || '%'
          or coalesce(p.summary, '') ilike '%' || p_query || '%')
     and (coalesce(p_category, '') = '' or c.slug = p_category)
     and (p_min_price is null or p.price_inr >= p_min_price)
     and (p_max_price is null or p.price_inr <= p_max_price)
     and (p_guests is null or p.max_guests >= p_guests)
     and (p_amenities is null or cardinality(p_amenities) = 0 or (
           select count(distinct a.slug) from public.property_amenities pa
             join public.amenities a on a.id = pa.amenity_id
            where pa.property_id = p.id and a.slug = any (p_amenities)
         ) = (select count(distinct x) from unnest(p_amenities) x))
     and (p_experiences is null or cardinality(p_experiences) = 0 or exists (
           select 1 from public.property_experiences pe
             join public.experiences e on e.id = pe.experience_id
            where pe.property_id = p.id and e.slug = any (p_experiences)
         ))
     and (p_check_in is null or p_check_out is null
          or public.is_property_available(p.id, p_check_in, p_check_out))
   order by
     case when p_sort = 'price_asc' then p.price_inr end asc nulls last,
     case when p_sort = 'price_desc' then p.price_inr end desc nulls last,
     case when p_sort = 'newest' then p.published_at end desc nulls last,
     p.is_featured desc, p.published_at desc nulls last, p.name
   limit greatest(least(coalesce(p_limit, 12), 48), 1) offset greatest(coalesce(p_offset, 0), 0)
$$;

-- Limited public view of hosts (name + verification only) for listings that are live.
create view public.host_public_profiles as
  select p.id, p.full_name, p.host_verified
    from public.profiles p
   where p.role = 'host'
     and not p.is_suspended
     and exists (select 1 from public.properties x where x.host_id = p.id and x.status = 'approved');

-- ---------------------------------------------------------------- function privileges
revoke all on function public.request_booking(uuid, date, date, int, int, text) from public, anon;
revoke all on function public.respond_to_booking(uuid, boolean, text) from public, anon;
revoke all on function public.cancel_booking(uuid, text) from public, anon;
revoke all on function public.submit_property(uuid) from public, anon;
revoke all on function public.review_property(uuid, text, text) from public, anon;
revoke all on function public.admin_update_user(uuid, public.app_role, boolean, boolean) from public, anon;
grant execute on function public.request_booking(uuid, date, date, int, int, text) to authenticated;
grant execute on function public.respond_to_booking(uuid, boolean, text) to authenticated;
grant execute on function public.cancel_booking(uuid, text) to authenticated;
grant execute on function public.submit_property(uuid) to authenticated;
grant execute on function public.review_property(uuid, text, text) to authenticated;
grant execute on function public.admin_update_user(uuid, public.app_role, boolean, boolean) to authenticated;
grant execute on function public.property_unavailable_ranges(uuid) to anon, authenticated;
grant execute on function public.is_property_available(uuid, date, date) to anon, authenticated;
grant execute on function public.search_properties(text, text, numeric, numeric, int, text[], text[], date, date, text, int, int) to anon, authenticated;
grant select on public.host_public_profiles to anon, authenticated;

-- ======================================================================
-- 20261017000200_rls.sql
-- ======================================================================
-- Hasiru Nidhi marketplace — Row Level Security
-- Principle: deny by default. A table with RLS enabled and no matching policy is inaccessible.

-- Ownership helper: true for the listing's host (while their account is active) or any admin.
create function public.owns_property(p_property uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public.is_admin() or exists (
    select 1 from public.properties p
     where p.id = p_property and p.host_id = auth.uid() and public.is_host()
  )
$$;
grant execute on function public.owns_property(uuid) to anon, authenticated;

alter table public.profiles enable row level security;
alter table public.property_categories enable row level security;
alter table public.amenities enable row level security;
alter table public.experiences enable row level security;
alter table public.properties enable row level security;
alter table public.property_private enable row level security;
alter table public.property_amenities enable row level security;
alter table public.property_experiences enable row level security;
alter table public.property_images enable row level security;
alter table public.room_types enable row level security;
alter table public.availability_blocks enable row level security;
alter table public.bookings enable row level security;
alter table public.saved_properties enable row level security;
alter table public.reviews enable row level security;
alter table public.notifications enable row level security;
alter table public.contact_enquiries enable row level security;
alter table public.partner_applications enable row level security;
alter table public.gardening_enquiries enable row level security;
alter table public.reports enable row level security;
alter table public.platform_settings enable row level security;
alter table public.audit_logs enable row level security;

-- ------------------------------------------------------------ profiles
create policy profiles_select on public.profiles for select to authenticated
  using (id = auth.uid() or public.is_admin());
create policy profiles_update_own on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());
-- (role / suspension / verification are additionally locked by profiles_guard; admins use admin_update_user())

-- ------------------------------------------------------------ catalogue
create policy categories_read on public.property_categories for select to anon, authenticated
  using (is_active or public.is_admin());
create policy categories_admin on public.property_categories for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy amenities_read on public.amenities for select to anon, authenticated
  using (is_active or public.is_admin());
create policy amenities_admin on public.amenities for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy experiences_read on public.experiences for select to anon, authenticated
  using (is_active or public.is_admin());
create policy experiences_admin on public.experiences for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- ------------------------------------------------------------ properties
create policy properties_select on public.properties for select to anon, authenticated
  using (status = 'approved' or host_id = auth.uid() or public.is_admin());
create policy properties_insert on public.properties for insert to authenticated
  with check (host_id = auth.uid() and public.is_host() and status = 'draft');
create policy properties_update on public.properties for update to authenticated
  using ((host_id = auth.uid() and public.is_host()) or public.is_admin())
  with check ((host_id = auth.uid() and public.is_host()) or public.is_admin());
create policy properties_delete on public.properties for delete to authenticated
  using ((host_id = auth.uid() and public.is_host() and status = 'draft') or public.is_admin());

create policy property_private_all on public.property_private for all to authenticated
  using (public.owns_property(property_id)) with check (public.owns_property(property_id));

-- Child rows are readable whenever the parent listing is readable by the caller.
create policy property_amenities_read on public.property_amenities for select to anon, authenticated
  using (exists (select 1 from public.properties p where p.id = property_id));
create policy property_amenities_write on public.property_amenities for all to authenticated
  using (public.owns_property(property_id)) with check (public.owns_property(property_id));

create policy property_experiences_read on public.property_experiences for select to anon, authenticated
  using (exists (select 1 from public.properties p where p.id = property_id));
create policy property_experiences_write on public.property_experiences for all to authenticated
  using (public.owns_property(property_id)) with check (public.owns_property(property_id));

create policy property_images_read on public.property_images for select to anon, authenticated
  using (exists (select 1 from public.properties p where p.id = property_id));
create policy property_images_write on public.property_images for all to authenticated
  using (public.owns_property(property_id)) with check (public.owns_property(property_id));

create policy room_types_read on public.room_types for select to anon, authenticated
  using (exists (select 1 from public.properties p where p.id = property_id));
create policy room_types_write on public.room_types for all to authenticated
  using (public.owns_property(property_id)) with check (public.owns_property(property_id));

-- Raw availability blocks (with the host's private reasons) are owner-only; the public gets
-- anonymised ranges through property_unavailable_ranges().
create policy availability_blocks_all on public.availability_blocks for all to authenticated
  using (public.owns_property(property_id)) with check (public.owns_property(property_id));

-- ------------------------------------------------------------ bookings (read-only for clients)
create policy bookings_select on public.bookings for select to authenticated
  using (traveller_id = auth.uid() or public.owns_property(property_id));
revoke insert, update, delete on public.bookings from anon, authenticated;
revoke all on public.bookings from anon;

-- ------------------------------------------------------------ saved / reviews / notifications
create policy saved_select on public.saved_properties for select to authenticated
  using (user_id = auth.uid());
create policy saved_insert on public.saved_properties for insert to authenticated
  with check (user_id = auth.uid() and exists (select 1 from public.properties p where p.id = property_id and p.status = 'approved'));
create policy saved_delete on public.saved_properties for delete to authenticated
  using (user_id = auth.uid());

create policy reviews_read on public.reviews for select to anon, authenticated
  using ((not is_hidden and exists (select 1 from public.properties p where p.id = property_id))
         or traveller_id = auth.uid() or public.is_admin());
create policy reviews_insert on public.reviews for insert to authenticated
  with check (
    traveller_id = auth.uid()
    and not is_hidden
    and exists (
      select 1 from public.bookings b
       where b.id = booking_id and b.traveller_id = auth.uid() and b.property_id = reviews.property_id
         and b.status in ('confirmed', 'completed') and b.check_out <= public.today_ist()
    )
  );
create policy reviews_admin_update on public.reviews for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy notifications_select on public.notifications for select to authenticated
  using (user_id = auth.uid());
create policy notifications_update on public.notifications for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
revoke insert, delete on public.notifications from anon, authenticated;
revoke update on public.notifications from authenticated;
grant update (is_read) on public.notifications to authenticated;
revoke all on public.notifications from anon;

-- ------------------------------------------------------------ enquiries & applications
create policy contact_insert on public.contact_enquiries for insert to anon, authenticated
  with check (status = 'new' and admin_notes is null and (user_id is null or user_id = auth.uid()));
create policy contact_select on public.contact_enquiries for select to authenticated
  using (public.is_admin() or user_id = auth.uid());
-- Hosts can read enquiries made about THEIR OWN listings (never anyone else's).
create policy contact_host_select on public.contact_enquiries for select to authenticated
  using (property_id is not null and public.owns_property(property_id));
create policy contact_admin_update on public.contact_enquiries for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy partner_insert on public.partner_applications for insert to anon, authenticated
  with check (status = 'new' and admin_notes is null and (user_id is null or user_id = auth.uid()));
create policy partner_select on public.partner_applications for select to authenticated
  using (public.is_admin() or user_id = auth.uid());
create policy partner_admin_update on public.partner_applications for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy gardening_insert on public.gardening_enquiries for insert to anon, authenticated
  with check (status = 'new' and admin_notes is null and (user_id is null or user_id = auth.uid()));
create policy gardening_select on public.gardening_enquiries for select to authenticated
  using (public.is_admin() or user_id = auth.uid());
create policy gardening_admin_update on public.gardening_enquiries for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy reports_insert on public.reports for insert to anon, authenticated
  with check (status = 'open' and (reporter_id is null or reporter_id = auth.uid())
              and exists (select 1 from public.properties p where p.id = property_id and p.status = 'approved'));
create policy reports_admin_select on public.reports for select to authenticated using (public.is_admin());
create policy reports_admin_update on public.reports for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- ------------------------------------------------------------ settings & audit
create policy settings_read on public.platform_settings for select to anon, authenticated
  using (is_public or public.is_admin());
create policy settings_admin on public.platform_settings for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy audit_admin_select on public.audit_logs for select to authenticated using (public.is_admin());
revoke insert, update, delete on public.audit_logs from anon, authenticated;
revoke all on public.audit_logs from anon;

